-- =====================================================================================
-- 0028 agent tamper protection (agent 7dc4487, 2026-11-16: Phase A)
--
-- The agent refuses sc stop / disable / delete / uninstall once it holds an unprotect
-- passcode, and accepts either that passcode or an Ed25519-signed token to stop or
-- uninstall. Credential model (Sam, 2026-11-16): one random passcode PER DEVICE,
-- generated by the server, stored only encrypted (AES-256-GCM under the secrets master
-- key, see internal/secretbox), shown to holders of agent.tamper.reveal (every reveal
-- is audited), rotated on a schedule. A console "stop agent" sends a short-lived
-- per-device token, never the passcode.
--
--   agent_unprotect_secrets  per agent: the passcode the agent has confirmed (applied_*)
--                            and the one in flight (pending_*). Both are kept because
--                            an offline agent still has the old one: that is the one an
--                            operator must be shown until the new one is confirmed.
--
-- Off by default (tamper.enabled = false): turning it on makes every agent refuse a
-- normal service stop, so an admin enables it deliberately.
-- New permissions agent.tamper (settings, rotate, stop) and agent.tamper.reveal (show a
-- passcode, mint a break-glass token): admin only, no role is seeded with them.
-- =====================================================================================

INSERT INTO system_settings (key, value, description) VALUES
    ('tamper.enabled',              'false', 'Give every agent a per-device unprotect passcode (turns on agent self-protection)'),
    ('tamper.rotation_days',        '30',    'Rotate each device''s unprotect passcode after this many days (0 = never)'),
    ('tamper.max_tries',            '3',     'Passcode attempts the agent''s GUI uninstall prompt allows'),
    ('tamper.silent_alert_minutes', '60',    'Raise an open agent tamper alert to critical when the device has been silent this long')
ON CONFLICT (key) DO NOTHING;

CREATE TABLE agent_unprotect_secrets (
    agent_id           UUID PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE,
    -- Secrets are nonce || AES-256-GCM ciphertext, sealed with AAD bound to agent_id and
    -- issued_at, so a ciphertext copied onto another row does not open. Never plaintext.
    key_id             TEXT,         -- master key that sealed them (secretbox.Box.KeyID)
    applied_secret     BYTEA,        -- the passcode the agent confirmed
    applied_issued_at  BIGINT,
    applied_at         TIMESTAMPTZ,
    pending_mode       TEXT CHECK (pending_mode IN ('set', 'clear')),
    pending_secret     BYTEA,        -- NULL for a clear
    pending_issued_at  BIGINT,
    pending_command_id UUID,
    pending_since      TIMESTAMPTZ,
    -- pending  a set/clear is in flight (re-sent on connect)
    -- applied  the agent holds applied_secret
    -- failed   the agent refused the last set/clear; retried after an agent upgrade
    -- cleared  protection was turned off on this agent
    status             TEXT NOT NULL CHECK (status IN ('pending', 'applied', 'failed', 'cleared')),
    reason             TEXT,
    agent_version      TEXT,         -- agent build that answered last (a 'failed' retry gate)
    rotate_after       TIMESTAMPTZ,  -- NULL = no scheduled rotation
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK ((pending_mode IS NULL) = (pending_issued_at IS NULL)),
    CHECK (pending_mode IS DISTINCT FROM 'set' OR pending_secret IS NOT NULL)
);
CREATE INDEX idx_aus_status ON agent_unprotect_secrets (status);
CREATE INDEX idx_aus_rotate ON agent_unprotect_secrets (rotate_after) WHERE status = 'applied';
CREATE INDEX idx_aus_pending ON agent_unprotect_secrets (pending_since) WHERE pending_mode IS NOT NULL;
